package com.escola.gestaoescolar.sige;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:sige;MODE=MySQL;DB_CLOSE_DELAY=-1;DATABASE_TO_LOWER=TRUE","spring.datasource.username=sa","spring.datasource.password=","spring.datasource.driver-class-name=org.h2.Driver"})
@Transactional
class WorkspaceTest {
 @Autowired Store store;@Autowired Workspace workspace;@Autowired Academic academic;@Autowired Operations operations;
 Store.Account admin(){return store.account("admin");}
 Workspace.Transaction change(ObjectNode before,String module,ObjectNode record){String key=Modules.get(module).key();return new Workspace.Transaction(before.path("revision").asLong(),List.of(new Workspace.Change(module,"upsert",record.path(key).asText(),record)),null);}
 @Test void seedIsConsistentAndSecretsNeverReturned(){ObjectNode db=store.load();workspace.validate(db);assertEquals(30,db.path("notas").size());assertEquals(20,db.path("pagamentos").size());assertFalse(db.toString().contains("admin123"));assertTrue(admin().password().startsWith("$2"));}
 @Test void studentsPersistAndOldRevisionsFail(){ObjectNode db=store.load(),student=Store.find(db,"alunos","ALU0001").deepCopy();student.put("Nome","Aluno actualizado");ObjectNode result=workspace.apply(admin(),change(db,"alunos",student));assertEquals("Aluno actualizado",Store.find(store.load(),"alunos","ALU0001").path("Nome").asText());assertEquals(db.path("revision").asLong()+1,result.path("revision").asLong());assertEquals(409,assertThrows(ApiException.class,()->workspace.apply(admin(),change(db,"alunos",student))).status);}
 @Test void financeCannotChangeStudents(){ObjectNode db=store.load(),student=Store.find(db,"alunos","ALU0001").deepCopy();student.put("Nome","Sem autorização");assertEquals(403,assertThrows(ApiException.class,()->workspace.apply(store.account("financeiro"),change(db,"alunos",student))).status);}
 @Test void teacherCanSubmitAnotherTermButCannotRewriteSubmission(){
  ObjectNode db=store.load(),grade=academic.grade(db,"1","9","2026/2027").deepCopy();grade.withObject("I_Trimestre").put("MAC",19);Store.Account teacher=store.account("professor");
  workspace.apply(teacher,change(db,"notas",grade));ObjectNode current=store.load(),saved=academic.grade(current,"1","9","2026/2027").deepCopy();assertTrue(saved.path("Locks").path("I_Trimestre").asBoolean());
  saved.withObject("I_Trimestre").put("MAC",18);assertEquals(403,assertThrows(ApiException.class,()->workspace.apply(teacher,change(current,"notas",saved))).status);
  ObjectNode other=academic.grade(current,"1","9","2026/2027").deepCopy();other.withObject("II_Trimestre").put("MAC",18);workspace.apply(teacher,change(current,"notas",other));
 }
 @Test void teacherCannotWriteOtherSubjectOrSeePayments(){ObjectNode db=store.load(),grade=academic.grade(db,"1","2","2026/2027").deepCopy();grade.withObject("I_Trimestre").put("MAC",20);assertEquals(403,assertThrows(ApiException.class,()->workspace.apply(store.account("professor"),change(db,"notas",grade))).status);ObjectNode view=workspace.snapshot(store.account("professor"));assertEquals(0,view.path("pagamentos").size());assertEquals(0,view.path("usuarios").size());assertTrue(view.path("alunos").size()<20);}
 @Test void invalidGradesRejectEntireTransaction(){ObjectNode db=store.load(),grade=academic.grade(db,"1","9","2026/2027").deepCopy();grade.withObject("I_Trimestre").put("MAC",21);assertEquals(422,assertThrows(ApiException.class,()->workspace.apply(admin(),change(db,"notas",grade))).status);assertNotEquals(21,academic.grade(store.load(),"1","9","2026/2027").path("I_Trimestre").path("MAC").asInt());}
 @Test void enrollmentMustMatchYearAndClassroom(){ObjectNode db=store.load(),enrollment=Store.find(db,"inscricoes","1").deepCopy();enrollment.put("Ano","2027/2028");assertEquals(422,assertThrows(ApiException.class,()->workspace.apply(admin(),change(db,"inscricoes",enrollment))).status);}
 @Test void incompleteAssessmentCannotApproveOrRenew(){ObjectNode db=store.load();assertEquals("Em curso",academic.result(db,"1").path("situacao").asText());ObjectNode result=operations.renew(admin(),new Operations.Renewal(db.path("revision").asLong(),"2026/2027","2027/2028"));assertEquals(0,result.path("renovadas").asInt());}
 @Test void completedAssessmentRenewsIntoDestinationClassroom(){
  ObjectNode db=store.load();for(String subject:List.of("9","12")){ObjectNode grade=academic.grade(db,"1",subject,"2026/2027");if(grade==null){grade=db.objectNode();grade.put("IdNota",Store.next(db,"notas","IdNota"));grade.put("CodInscricao",1);grade.put("CodMateria",Integer.parseInt(subject));grade.put("Ano","2026/2027");((ArrayNode)db.path("notas")).add(grade);}for(String term:Academic.TERMS)for(String type:Academic.TYPES)grade.withObject(term).put(type,15);grade.put("ExameFinal",15);store.upsert(Modules.get("notas"),grade);}
  settle(1);assertEquals("Aprovado",academic.result(store.load(),"1").path("situacao").asText());ObjectNode result=operations.renew(admin(),new Operations.Renewal(db.path("revision").asLong(),"2026/2027","2027/2028"));assertEquals(1,result.path("renovadas").asInt());ObjectNode fresh=Store.find(result,"inscricoes","21"),turma=Store.find(result,"turmas",fresh.path("CodTurma").asText());assertEquals("2027/2028",turma.path("Ano").asText());assertEquals("11ª Classe",turma.path("Classe").asText());assertEquals("Pendente",fresh.path("Estado").asText());assertTrue(result.path("elegibilidadeExportacao").path("21").path("elegivel").asBoolean());
 }
 @Test void zeroWeightAndZeroNegativesRemainValid(){ObjectNode db=store.load();db.withObject("config").put("pesoExameFinal",0).put("pesoMediaAnual",1);Store.find(db,"classes","1").withObject("PorAno").withObject("2026/2027").put("MaxNegativas",0);workspace.validate(db);ObjectNode grade=academic.grade(db,"1","9","2026/2027");grade.put("ExameFinal",0);assertEquals(academic.annual(grade),academic.finalGrade(grade,db.path("config"),false));}

 void settle(int enrollment){ObjectNode db=store.load(),ins=Store.find(db,"inscricoes",String.valueOf(enrollment)),payment=db.objectNode();payment.put("IdPagamento",Store.next(db,"pagamentos","IdPagamento"));payment.put("CodAluno",ins.path("CodAluno").asText());payment.put("CodInscricao",enrollment);payment.put("Referente","Propina Anual");payment.put("Talao","TESTE-"+enrollment);payment.put("Data",java.time.LocalDate.now().toString());payment.put("FormaPagamento","Numerário");payment.put("Valor",100000);store.upsert(Modules.get("pagamentos"),payment);}
 void completeFirst(){ObjectNode db=store.load();for(int subject:List.of(9,12)){ObjectNode grade=academic.grade(db,"1",String.valueOf(subject),"2026/2027");if(grade==null){grade=db.objectNode();grade.put("IdNota",Store.next(db,"notas","IdNota"));grade.put("CodInscricao",1);grade.put("CodMateria",subject);grade.put("Ano","2026/2027");((ArrayNode)db.path("notas")).add(grade);}for(String term:Academic.TERMS)for(String kind:Academic.TYPES)grade.withObject(term).put(kind,15);grade.put("ExameFinal",15);store.upsert(Modules.get("notas"),grade);}}
 @Test void secretaryCannotPostPaymentsAndFinanceCannotEnroll(){ObjectNode db=store.load();assertEquals(403,assertThrows(ApiException.class,()->workspace.apply(store.account("secretaria"),change(db,"pagamentos",Store.find(db,"pagamentos","1").deepCopy()))).status);assertEquals(403,assertThrows(ApiException.class,()->workspace.apply(store.account("financeiro"),change(db,"inscricoes",Store.find(db,"inscricoes","1").deepCopy()))).status);}
 @Test void decimalsAreRejectedInTermsAndExams(){ObjectNode db=store.load(),grade=academic.grade(db,"1","9","2026/2027").deepCopy();grade.withObject("I_Trimestre").put("NPT",14.5);assertEquals(422,assertThrows(ApiException.class,()->workspace.apply(admin(),change(db,"notas",grade))).status);grade.withObject("I_Trimestre").put("NPT",14);grade.put("ExameFinal",13.5);assertEquals(422,assertThrows(ApiException.class,()->workspace.apply(admin(),change(db,"notas",grade))).status);}
 @Test void teacherSnapshotCannotRevealOtherSubjectsOrWholeReport(){ObjectNode db=workspace.snapshot(store.account("professor"));assertTrue(db.path("resultados").isEmpty());assertTrue(db.path("propinas").isEmpty());for(var grade:db.path("notas"))assertEquals("9",grade.path("CodMateria").asText());for(var student:db.path("alunos")){assertFalse(student.has("Movel1"));assertFalse(student.has("Encarregado"));assertFalse(student.has("Morada"));}}
 @Test void newTeacherGradeLocksOnlyTheSubmittedTerm(){ObjectNode db=store.load(),grade=db.objectNode();grade.put("IdNota",999);grade.put("CodInscricao",7);grade.put("CodMateria",9);grade.put("Ano","2026/2027");for(String term:Academic.TERMS)for(String kind:Academic.TYPES)grade.withObject(term).putNull(kind);grade.withObject("I_Trimestre").put("MAC",14).put("NPP",15).put("NPT",16);grade.putNull("ExameFinal");grade.putNull("ExameRecurso");ObjectNode result=workspace.apply(store.account("professor"),change(db,"notas",grade));ObjectNode saved=Store.find(result,"notas","999");assertTrue(saved.path("Locks").path("I_Trimestre").asBoolean());assertFalse(saved.path("Locks").path("II_Trimestre").asBoolean());}
 @Test void annualTariffsPreserveEarlierDebtAndDeriveTheTotal(){ObjectNode db=store.load(),ins=Store.find(db,"inscricoes","1"),cls=Store.find(db,"classes","3").deepCopy();double oldDebt=SchoolYear.billing(db,ins).path("divida").asDouble();ObjectNode future=cls.withObject("PorAno").withObject("2027/2028");future.put("Propina",999).put("Duracao",10).put("Inscricao",100).put("Valor",1);workspace.apply(admin(),change(db,"classes",cls));ObjectNode saved=store.load();assertEquals(10090,SchoolYear.classFor(saved,"10ª Classe","2027/2028").path("Valor").asInt());assertEquals(oldDebt,SchoolYear.billing(saved,ins).path("divida").asDouble());}
 @Test void debtPreventsRenewalEvenWhenAssessmentIsComplete(){completeFirst();ObjectNode db=store.load();assertFalse(SchoolYear.billing(db,Store.find(db,"inscricoes","1")).path("emDia").asBoolean());ObjectNode result=operations.renew(admin(),new Operations.Renewal(db.path("revision").asLong(),"2026/2027","2027/2028"));assertEquals(0,result.path("renovadas").asInt());}
 @Test void exportChecksOriginAndConfirmationIsExplicit(){completeFirst();settle(1);ObjectNode db=store.load();operations.renew(admin(),new Operations.Renewal(db.path("revision").asLong(),"2026/2027","2027/2028"));db=store.load();String csv=operations.exportRenewals(store.account("secretaria"),"2027/2028");assertTrue(csv.contains("ALU0001"));assertFalse(csv.contains("Encarregado"));assertFalse(csv.contains("DataNa"));assertFalse(csv.contains("Morada"));ObjectNode pending=Store.find(db,"inscricoes","21").deepCopy();pending.put("Estado","Matriculado");workspace.apply(store.account("secretaria"),change(db,"inscricoes",pending));assertEquals("secretaria",Store.find(store.load(),"inscricoes","21").path("ConfirmadoPor").asText());assertFalse(operations.exportRenewals(admin(),"2027/2028").contains("ALU0001"));assertEquals(403,assertThrows(ApiException.class,()->operations.exportRenewals(store.account("professor"),"2027/2028")).status);}
 @Test void confirmationRechecksDebtInsteadOfTrustingPreview(){completeFirst();settle(1);ObjectNode db=store.load();operations.renew(admin(),new Operations.Renewal(db.path("revision").asLong(),"2026/2027","2027/2028"));db=store.load();ObjectNode payment=Store.find(db,"pagamentos","Talao","TESTE-1");store.delete(Modules.get("pagamentos"),payment.path("IdPagamento").asText());ObjectNode current=store.load(),pending=Store.find(current,"inscricoes","21").deepCopy();pending.put("Estado","Matriculado");assertEquals(422,assertThrows(ApiException.class,()->workspace.apply(admin(),change(current,"inscricoes",pending))).status);assertFalse(operations.exportRenewals(admin(),"2027/2028").contains("ALU0001"));}
 @Test void tuitionFromAnotherEnrollmentNeverSettlesThisDebt(){ObjectNode db=store.load(),original=Store.find(db,"inscricoes","1");double debt=SchoolYear.billing(db,original).path("divida").asDouble();settle(2);assertEquals(debt,SchoolYear.billing(store.load(),original).path("divida").asDouble());}
}
